/**
 * Deleted-rule memory for the auto-rule generator. Category rules are
 * hard-deleted, so when the user deletes a junk auto-generated rule a
 * `CategoryRuleTombstone` keeps its spec, and the generator skips any later
 * candidate for the same category that the deleted rule already covered.
 */
import type { Logger } from "@nestjs/common";
import { Repository } from "typeorm";

import { CATEGORY_RULE_MATCH_MODES } from "../constants/domain-types";
import {
  CategoryRule,
  CompositeCategoryRuleSpec,
} from "../database/entities/category-rule.entity";
import { CategoryRuleTombstone } from "../database/entities/category-rule-tombstone.entity";
import { compositeSpecWithinPositiveConditions } from "./category-rules-auto-composite.helper";

type TombstoneRepository = Repository<CategoryRuleTombstone>;

/** The user's tombstones for one category (empty when the category is unknown). */
export function loadCategoryTombstones(
  repository: TombstoneRepository,
  userId: string,
  categoryId: string | null,
): Promise<CategoryRuleTombstone[]> {
  if (!categoryId) {
    return Promise.resolve([]);
  }
  return repository.find({ where: { userId, categoryId } });
}

/**
 * The tombstone whose deleted rule was the same as `candidateSpec` or broader,
 * or null. Callers pass tombstones for the candidate's category only.
 */
export function findTombstoneCoveringSpec(
  tombstones: CategoryRuleTombstone[],
  candidateSpec: CompositeCategoryRuleSpec,
): CategoryRuleTombstone | null {
  return (
    tombstones.find((tombstone) =>
      compositeSpecWithinPositiveConditions(
        tombstone.compositeSpec,
        candidateSpec,
      ),
    ) ?? null
  );
}

export interface DeletedRuleCheckParams {
  repository: TombstoneRepository;
  logger: Pick<Logger, "log">;
  userId: string;
  categoryId: string | null;
  categoryName: string;
}

/** Answers (and logs) whether the user already deleted a rule covering a candidate. */
export type DeletedRuleCheck = (
  candidateSpec: CompositeCategoryRuleSpec,
) => boolean;

/**
 * Loads the category's tombstones once and returns a check the generator can
 * run on the candidate both before and after its gates.
 */
export async function loadDeletedRuleCheck(
  params: DeletedRuleCheckParams,
): Promise<DeletedRuleCheck> {
  const { repository, logger, userId, categoryId, categoryName } = params;
  const tombstones = await loadCategoryTombstones(
    repository,
    userId,
    categoryId,
  );
  return (candidateSpec) => {
    const tombstone = findTombstoneCoveringSpec(tombstones, candidateSpec);
    if (!tombstone) {
      return false;
    }
    logger.log(
      `[CategoryRules] Skipping auto composite rule — user ${userId} deleted rule ${tombstone.deletedRuleId} covering it in category="${categoryName}"`,
    );
    return true;
  };
}

type TombstonableRule = CategoryRule & {
  categoryId: string;
  compositeSpec: CompositeCategoryRuleSpec;
};

/**
 * Only generator-made composite rules are remembered: a rule the user wrote
 * themselves is theirs to recreate, and a rule without a category can never
 * match a candidate.
 */
function isTombstonable(rule: CategoryRule): rule is TombstonableRule {
  return (
    rule.isAutoGenerated &&
    rule.ruleKind === CATEGORY_RULE_MATCH_MODES.COMPOSITE &&
    rule.categoryId != null &&
    rule.compositeSpec != null
  );
}

/**
 * Records a tombstone for `rule` if it is an auto-generated composite rule
 * that no existing tombstone already covers. Returns the new row, or null when
 * nothing needed recording.
 */
export async function recordTombstoneForDeletedRule(
  repository: TombstoneRepository,
  rule: CategoryRule,
): Promise<CategoryRuleTombstone | null> {
  if (!isTombstonable(rule)) {
    return null;
  }
  const existing = await loadCategoryTombstones(
    repository,
    rule.userId,
    rule.categoryId,
  );
  if (findTombstoneCoveringSpec(existing, rule.compositeSpec)) {
    return null;
  }
  return repository.save(
    repository.create({
      userId: rule.userId,
      categoryId: rule.categoryId,
      compositeSpec: rule.compositeSpec,
      deletedRuleId: rule.id,
    }),
  );
}

/**
 * Deletes a user's rule, first recording a tombstone when it is an
 * auto-generated one. The tombstone is written first: if that fails the rule
 * survives for a retry, instead of being deleted with the rejection forgotten.
 * Returns false when the user has no such rule.
 */
export async function deleteRuleRememberingAutoRules(
  ruleRepository: Repository<CategoryRule>,
  tombstoneRepository: TombstoneRepository,
  userId: string,
  ruleId: string,
): Promise<boolean> {
  const rule = await ruleRepository.findOne({ where: { id: ruleId, userId } });
  if (!rule) {
    return false;
  }
  await recordTombstoneForDeletedRule(tombstoneRepository, rule);
  const result = await ruleRepository.delete({ id: ruleId, userId });
  return (result.affected ?? 0) > 0;
}
